using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

public class RunesPanelCellarius
{
	public void ToggleActionValueModifier(ActionValueModifier actionValueModifier, List<RuneInstance> runeInstances, MonoBehaviour mono, Rune[] runes, PlayerCurrentRunes playerCurrentRunes, float playerCurrentCorruption)
	{
		for (int i = 0; i < runeInstances.Count; i++)
		{
			if (!(runeInstances[i] == null))
			{
				runeInstances[i].Rune.ToggleActionValueModifier(new List<ActionValueModifier> { actionValueModifier });
				runeInstances[i].UpdateActionFace();
			}
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(mono, 3, delegate
		{
			UpdateRunesEmpower(runes, playerCurrentRunes, runeInstances, playerCurrentCorruption);
		});
	}

	private void UpdateRunesEmpower(Rune[] runes, PlayerCurrentRunes playerCurrentRunes, List<RuneInstance> runeInstances, float playerCurrentCorruption)
	{
		if (runes[0].BattleAction != null)
		{
			if (!playerCurrentRunes.usedRuneIndexes.Contains(0))
			{
				runeInstances[0].ToggleActionFace(toggle: true);
			}
			else
			{
				runeInstances[0].ToggleActionFace(toggle: false);
			}
		}
		for (int i = 1; i < runes.Length; i++)
		{
			if (!(runeInstances[i] == null))
			{
				if (playerCurrentRunes.activeRuneIndexes.Contains(i))
				{
					runeInstances[i].ToggleActionFace(toggle: true);
				}
				else if ((float)i <= playerCurrentCorruption && (bool)runes[i].BattleAction && !playerCurrentRunes.usedRuneIndexes.Contains(runeInstances[i].Rune.index))
				{
					runeInstances[i].ToggleActionFace(toggle: true);
				}
				else if (!playerCurrentRunes.activeRuneIndexes.Contains(i))
				{
					runeInstances[i].ToggleActionFace(toggle: false);
				}
			}
		}
	}
}
